converted_query_dql:
timeseries {
    numerator = sum(dt.kubernetes.container.restarts, rate: 1m),
    denominator = count(dt.kubernetes.pods)
  },
  by: { k8s.cluster.name, k8s.workload.name },
  filter: {
    k8s.cluster.name  ==  "usf-app-prod-panamax-eks-cluster" and k8s.workload.name  ==  "panamax-alerts-events-processing-domain-api"
  }
| fieldsAdd value = (numerator[] / denominator[]) * 100
| fieldsRemove numerator, denominator

